/* Loads data/games.json + data/marker-types.json and indexes every map
 * by its key ("<game>/<map>", e.g. "sly2/paris"). */

import { isCalibrated } from './coords.js';

async function fetchJson(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to load ${url}: ${response.status}`);
  }
  return response.json();
}

export async function loadManifest() {
  const [catalog, markerTypes, assets] = await Promise.all([
    fetchJson('./data/games.json'),
    fetchJson('./data/marker-types.json'),
    // generated by `npm run tiles`; maps without tiles fall back to the full image
    fetchJson('./data/assets.json').catch(() => ({})),
  ]);

  const maps = new Map();
  catalog.games.forEach((game) => {
    game.short ??= game.title;
    game.entries = [];  // the game's maps in play order
    game.episodes.forEach((episode) => {
      episode.label ??= episode.number ? `Episode ${episode.number}` : '';
      episode.entries = [];
      episode.maps.forEach((map) => {
        const key = `${game.id}/${map.id}`;
        if (maps.has(key)) {
          console.error(`Duplicate map key in games.json: ${key}`);
        }
        if (map.calib && !isCalibrated(map.calib)) {
          console.error(`Map ${key} has an invalid calib (needs origin [x, y] and scale > 0)`);
        }
        const entry = { ...map, key, data: map.data ?? [], assets: assets[key] ?? null, game, episode };
        maps.set(key, entry);
        episode.entries.push(entry);
        game.entries.push(entry);
      });
    });
  });

  // links between maps ({ to: "<game>/<map>", at: [x, y] }), both directions
  maps.forEach((entry) => {
    entry.links = (entry.links ?? []).filter((link) => {
      if (!maps.has(link.to)) {
        console.error(`Map ${entry.key} links to unknown map ${link.to}`);
        return false;
      }
      return true;
    }).map((link) => ({ ...link, target: maps.get(link.to) }));
    entry.linkedFrom = [];
  });
  maps.forEach((entry) => entry.links.forEach((link) => {
    if (!link.target.linkedFrom.includes(entry)) {
      link.target.linkedFrom.push(entry);
    }
  }));

  return {
    games: catalog.games,
    maps,
    markerTypes,
    // map images live under assetBase (the site itself, or a CDN bucket)
    assetBase: catalog.assetBase ?? './',
    defaultKey: maps.has(catalog.default) ? catalog.default : maps.keys().next().value,
    findGame: (id) => catalog.games.find((game) => game.id === id),
    previewUrl: (entry) => entry.assets?.preview ? (catalog.assetBase ?? './') + entry.assets.preview : null,
    // old ?map=paris links used bare map ids
    findByMapId: (id) => [...maps.values()].find((map) => map.id === id),
  };
}
